import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist - but sortDir is not validated
        String[] allowedCols = {"created_at", "amount", "department", "employee_name"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) { validSort = true; break; }
            }
        }
        if (sortCol != null && !validSort) {
            sortCol = "created_at";
        }

        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, employee_name, department, amount, created_at ");
        sql.append("FROM expense_reports WHERE created_at BETWEEN ? AND ? ");

        if (department != null && !department.isEmpty()) {
            // Developer note: department comes from dropdown, safe to inline
            sql.append("AND department = '").append(department).append("' ");
        }

        if (reportType.equals("pending")) {
            sql.append("AND status = 'PENDING' ");
        } else if (reportType.equals("approved")) {
            sql.append("AND status = 'APPROVED' ");
        }

        if (sortCol != null) {
            sql.append("ORDER BY ").append(sortCol);
            if (sortDir != null) {
                // sortDir should be ASC or DESC
                sql.append(" ").append(sortDir);
            }
        }

        sql.append(" LIMIT 500");

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql.toString())) {

            ps.setString(1, startDate);
            ps.setString(2, endDate);

            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"dept\":\"%s\",\"amount\":%.2f,\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("employee_name"),
                    rs.getString("department"),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
